scripts.紫轩对话.txt:
	
	If ($Event == 144) @Label1;
	If ($Event == 170) @Label2;
	If ($Event == 146) @Label3;
	Goto @end;

@Label1:
	If ($ZiXuanSense >> 20) @AddSenseEnd;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd:
	Say("紫轩：杨公子，我无父无母，没有可以倾诉心事的人，今天能够遇见公子，我…真开心！", 122);	
	Say("杨影枫：紫轩姑娘，我们能够相遇，也许就是传说中的缘份吧？",	120);
	Return;
	
	
@Label2:	
	If ($Talkzixuan18 == 0) @Talk0;
	If ($Talkzixuan18 == 1) @Talk1;	
	Goto @end;
@Talk0:
	If ($ZiXuanSense >> 20) @AddSenseEnd1;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd1:
	Talk(2386, 2388);
	Assign($Talkzixuan18, 1);
	Return;
@Talk1:
	If ($ZiXuanSense >> 20) @AddSenseEnd2;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd2:	
	Say("紫轩：杨大哥，你秉性纯良，太容易相信人了……",	16);
	Return;


@Label3:
	If ($ZiXuanSense >> 20) @AddSenseEnd3;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd3:
	Say("紫轩：杨公子，你从小一个人在深山长大，不会觉得寂寞吗？", 16);
	Say("杨影枫：在山里的时候我不理世事，潜心修炼武功，每天想的就是如何练好武功，将来成为武林第一，哪有时间寂寞呀，哈哈！", 3);
	Say("紫轩：武林第一？", 16);
	Say("杨影枫：对，这是我爹临死前对我的期望，也是天下所有习武之人的梦想！", 2);
	Say("紫轩：……", 17);
	Return;

@end:
	Return;

